  maintenanciers: { title: 'Maintenanciers', eyebrow: 'GESTION DES UTILISATEURS', subtitle: 'Contrôlez les compétences, zones et certifications.', icon: Wrench, columns: ['Prestataire', 'Spécialités', 'Zone', 'Note', 'Statut'], rows: [['Mécano Pro SARL', 'Moteurs diesel', 'Parakou', '4.6 / 5', 'À valider'], ['Atelier Agri Nord', 'Hydraulique', 'Cotonou', '4.8 / 5', 'À valider'], ['Service Tracteur BJ', 'Maintenance', 'Abomey-Calavi', '4.5 / 5', 'Validé'], ['Irrigation Solutions', 'Pompes et irrigation', 'Porto-Novo', '4.9 / 5', 'Actif']] },
  agriculteurs: { title: 'Agriculteurs', eyebrow: 'GESTION DES UTILISATEURS', subtitle: 'Suivez les exploitants et leur activité sur AGRIMAC.', icon: Tractor, columns: ['Agriculteur', 'Activité', 'Localisation', 'Dernière activité', 'Statut'], rows: [['Koffi Agbodan', 'Culture de maïs', 'Cotonou', 'Aujourd’hui', 'Actif'], ['Euloge Dossou', 'Maraîchage', 'Porto-Novo', 'Hier', 'Actif'], ['Jean Hounkpe', 'Élevage', 'Parakou', '12 Juin 2025', 'Suspendu'], ['Awa Sika', 'Culture de coton', 'Bohicon', '11 Juin 2025', 'Actif']] },
  annonces: { title: 'Annonces & produits', eyebrow: 'CONTENU & ANNONCES', subtitle: 'Modérez les publications et les contenus du marketplace.', icon: Package, columns: ['Annonce', 'Vendeur', 'Catégorie', 'Vues', 'Statut'], rows: [['Massey Ferguson 375', 'Agri Services Pro', 'Machine agricole', '2 456', 'Publié'], ['Motopompe Hyundai', 'Farm Equipement', 'Équipement', '3 842', 'À modérer'], ['Engrais NPK 20-10-10', 'Agri Services Pro', 'Intrant agricole', '1 256', 'Publié'], ['Herse à disques 18 disques', 'Bénin Agro Distribution', 'Équipement', '1 098', 'Brouillon']] },
  categories: { title: 'Catégories', eyebrow: 'CONTENU & ANNONCES', subtitle: 'Organisez les familles de produits et de services.', icon: Package, columns: ['Catégorie', 'Annonces', 'Dernière mise à jour', 'Ordre', 'Statut'], rows: [['Machines agricoles', '42', 'Aujourd’hui', '1', 'Actif'], ['Pièces détachées', '86', 'Aujourd’hui', '2', 'Actif'], ['Services de maintenance', '31', 'Hier', '3', 'Actif'], ['Intrants agricoles', '54', '12 Juin 2025', '4', 'Brouillon']] },
