function AdminProductsConnected() {
  const [items, setItems] = useState([]); const [query, setQuery] = useState(''); const [status, setStatus] = useState(''); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [selected, setSelected] = useState(null); const [actionId, setActionId] = useState('');
  const load = async () => { setLoading(true); setError(''); try { const data = await resources.admin.products(); setItems(Array.isArray(data) ? data : data?.items || []); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Impossible de charger les annonces.'); } finally { setLoading(false); } };
  useEffect(() => { load(); }, []);
  const filtered = items.filter(item => `${productText(item.title)} ${productText(item.company?.legalName)} ${productText(item.category?.name)} ${productText(item.city)} ${productText(item.region)}`.toLowerCase().includes(query.toLowerCase()) && (!status || item.status === status));
  const moderate = async (product, nextStatus) => { if (!product?.id || actionId) return; if (!window.confirm(`Confirmer : ${productStatusLabels[nextStatus] || nextStatus} « ${productText(product.title)} » ?`)) return; setActionId(product.id); try { const updated = await resources.admin.moderateProduct(product.id, { status: nextStatus }); setItems(current => current.map(item => item.id === product.id ? { ...item, status: updated.status } : item)); setSelected(current => current?.id === product.id ? { ...current, status: updated.status } : current); notify(`${productText(product.title)} : ${productStatusLabels[updated.status] || updated.status}.`); } catch (reason) { notify(reason instanceof Error ? reason.message : 'La modération n’a pas pu être enregistrée.', 'error'); } finally { setActionId(''); } };
  const reset = () => { setQuery(''); setStatus(''); };
  return <SidebarFrame title="Annonces & produits" eyebrow="CONTENU & ANNONCES" subtitle="Modérez les publications réelles du marketplace AGRIMAC." icon={Package} action={<div className="admin-sidebar-actions"><button className="admin-sidebar-secondary" disabled title="Endpoint d’export annonces indisponible"><Download size={14} /> Export indisponible</button><button className="admin-sidebar-primary" disabled title="Aucun endpoint Admin de création d’annonce"><UserPlus size={14} /> Ajouter indisponible</button></div>}><div className="admin-sidebar-kpis"><Kpi icon={Package} value={items.length.toLocaleString('fr-FR')} label="Annonces chargées" detail="Réponse backend" /><Kpi icon={CheckCircle2} value={items.filter(item => item.status === 'PUBLISHED').length} label="Publiées" detail="Données chargées" tone="green" /><Kpi icon={AlertTriangle} value={items.filter(item => item.status === 'DRAFT').length} label="À modérer" detail="Brouillons" tone="amber" /><Kpi icon={Filter} value={`${filtered.length}/${items.length}`} label="Résultats" detail="Filtrage local" /></div><section className="admin-sidebar-panel"><header className="admin-sidebar-panel-heading"><div><h3>Gestion des annonces</h3><p>Recherche et filtre locaux sur les produits réellement retournés par l’API.</p></div><span className="admin-sidebar-result"><CheckCircle2 size={14} /> {filtered.length} résultat(s)</span></header><div className="admin-sidebar-toolbar"><label><Search size={15} /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Titre, vendeur ou catégorie..." /></label><select value={status} onChange={event => setStatus(event.target.value)} aria-label="Filtrer les annonces par statut"><option value="">Tous les statuts</option>{Object.entries(productStatusLabels).map(([key, label]) => <option value={key} key={key}>{label}</option>)}</select><button className="admin-sidebar-reset" onClick={reset}><RefreshCw size={14} /> Réinitialiser</button><button className="admin-sidebar-reset" onClick={load} disabled={loading}><RefreshCw size={14} className={loading ? 'admin-sidebar-spin' : ''} /> Actualiser</button></div>{loading ? <AdminUsersState label="Chargement des annonces..." /> : error ? <AdminUsersState label={error} error onRetry={load} /> : !filtered.length ? <AdminUsersState label={items.length ? 'Aucune annonce correspondante.' : 'Aucune annonce retournée par le backend.'} empty /> : <div className="admin-sidebar-table admin-products-table"><header><span>Annonce</span><span>Vendeur</span><span>Catégorie</span><span>Prix / stock</span><span>Statut</span><span>Action</span></header>{filtered.map(product => <div className="admin-sidebar-table-row" key={product.id}><span className="admin-user-cell"><i>{productText(product.title, 'A').slice(0, 1).toUpperCase()}</i><b>{productText(product.title)}<small>{productText(product.description, 'Description indisponible')}</small></b></span><span>{productText(product.company?.legalName)}</span><span>{productKindLabels[product.kind] || productText(product.category?.name)}</span><span>{product.priceXof == null ? '—' : `${Number(product.priceXof).toLocaleString('fr-FR')} FCFA`} · {product.stock == null ? '—' : `${product.stock} stock`}</span><Status>{productStatusLabels[product.status] || productText(product.status)}</Status><button className="admin-user-view" onClick={() => setSelected(product)}>Consulter <Eye size={13} /></button></div>)}</div>}</section>{selected && <AdminProductDetail product={selected} actionId={actionId} onClose={() => setSelected(null)} onModerate={moderate} />}</SidebarFrame>;
}
