function AdminProductDetail({ product, actionId, onClose, onModerate }) { const actions = product.status === 'DRAFT' ? [['PUBLISHED', 'Publier']] : product.status === 'PUBLISHED' ? [['DRAFT', 'Dépublier'], ['ARCHIVED', 'Archiver']] : [['DRAFT', 'Restaurer']]; return <div className="admin-sidebar-overlay" onMouseDown={event => event.target === event.currentTarget && onClose()}><aside className="admin-sidebar-drawer"><header><div><span className="admin-sidebar-eyebrow">DÉTAIL ANNONCE</span><h3>{productText(product.title)}</h3></div><button onClick={onClose} aria-label="Fermer"><X size={17} /></button></header><div className="admin-sidebar-drawer-avatar">{productText(product.title, 'A').slice(0, 1).toUpperCase()}</div><dl><div><dt>ID</dt><dd>{productText(product.id)}</dd></div><div><dt>Vendeur</dt><dd>{productText(product.company?.legalName)}</dd></div><div><dt>Type</dt><dd>{productKindLabels[product.kind] || productText(product.kind)}</dd></div><div><dt>Catégorie</dt><dd>{productText(product.category?.name)}</dd></div><div><dt>Description</dt><dd>{productText(product.description)}</dd></div><div><dt>Prix</dt><dd>{product.priceXof == null ? '—' : `${Number(product.priceXof).toLocaleString('fr-FR')} FCFA`}</dd></div><div><dt>Stock</dt><dd>{product.stock == null ? '—' : product.stock}</dd></div><div><dt>Localisation</dt><dd>{productText(product.city || product.region)}</dd></div><div><dt>Créée le</dt><dd>{productDate(product.createdAt)}</dd></div></dl><div className="admin-sidebar-drawer-security"><ShieldCheck size={17} /><span><b>Modération journalisée</b><small>Les changements de statut sont enregistrés par le backend.</small></span></div><footer>{actions.map(([nextStatus, label]) => <button key={nextStatus} className={nextStatus === 'ARCHIVED' ? 'admin-sidebar-danger' : 'admin-sidebar-primary'} disabled={actionId === product.id} onClick={() => onModerate(product, nextStatus)}>{actionId === product.id ? <LoaderCircle size={14} className="admin-sidebar-spin" /> : <Check size={14} />} {actionId === product.id ? 'Enregistrement...' : label}</button>)}<button className="admin-sidebar-secondary" onClick={onClose}>Fermer</button></footer></aside></div>; }

function AdminUsersConnected() {
  const [items, setItems] = useState([]); const [total, setTotal] = useState(0); const [page, setPage] = useState(1); const [query, setQuery] = useState(''); const [role, setRole] = useState(''); const [status, setStatus] = useState(''); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [selected, setSelected] = useState(null); const [actionId, setActionId] = useState(''); const limit = 25;
  const load = async (nextPage = page) => { setLoading(true); setError(''); try { const result = await resources.admin.users({ limit, skip: (nextPage - 1) * limit, ...(query.trim() ? { q: query.trim() } : {}), ...(role ? { role } : {}), ...(status ? { status } : {}) }); setItems(Array.isArray(result?.items) ? result.items : []); setTotal(Number.isFinite(Number(result?.total)) ? Number(result.total) : 0); setPage(nextPage); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Impossible de charger les utilisateurs.'); } finally { setLoading(false); } };
  useEffect(() => { load(1); }, [role, status]);
  const totalPages = Math.max(1, Math.ceil(total / limit));
  const action = async (user, nextAction) => { if (!user?.id || actionId) return; const labels = { approve: 'valider', suspend: 'suspendre', reactivate: 'réactiver' }; if (!window.confirm(`Confirmer : ${labels[nextAction]} ${userName(user)} ?`)) return; setActionId(user.id); try { const updated = await resources.admin[nextAction](user.id); setItems(current => current.map(item => item.id === user.id ? { ...item, status: updated.status } : item)); if (selected?.id === user.id) setSelected(current => ({ ...current, status: updated.status })); notify(`${userName(user)} : ${userStatusLabels[updated.status] || updated.status}.`); } catch (reason) { notify(reason instanceof Error ? reason.message : 'L’action n’a pas pu être enregistrée.', 'error'); } finally { setActionId(''); } };
  const openDetail = async user => { setSelected({ ...user, loading: true }); try { const detail = await resources.admin.user(user.id); setSelected(detail); } catch (reason) { setSelected({ ...user, detailError: reason instanceof Error ? reason.message : 'Détail indisponible.', loading: false }); } };
  const reset = () => { setQuery(''); setRole(''); setStatus(''); load(1); };
  const rows = items;
  return <SidebarFrame title="Utilisateurs" eyebrow="GESTION DES UTILISATEURS" subtitle="Supervisez les comptes, les rôles et l’activité réelle de la communauté." icon={Users} action={<div className="admin-sidebar-actions"><button className="admin-sidebar-secondary" disabled title="Endpoint d’export utilisateurs indisponible"><Download size={14} /> Export indisponible</button><button className="admin-sidebar-primary" disabled title="Aucun endpoint de création utilisateur Admin disponible"><UserPlus size={14} /> Ajouter indisponible</button></div>}><div className="admin-sidebar-kpis"><Kpi icon={Users} value={total.toLocaleString('fr-FR')} label="Utilisateurs" detail="Total backend" /><Kpi icon={CheckCircle2} value={rows.filter(user => ['ACTIVE', 'APPROVED'].includes(user.status)).length} label="Conformes" detail="Page courante" tone="green" /><Kpi icon={AlertTriangle} value={rows.filter(user => ['PENDING', 'SUSPENDED', 'REJECTED'].includes(user.status)).length} label="À traiter" detail="Page courante" tone="amber" /><Kpi icon={Filter} value={`${rows.length}/${total || 0}`} label="Résultats" detail="Page courante" /></div><section className="admin-sidebar-panel"><header className="admin-sidebar-panel-heading"><div><h3>Gestion des utilisateurs</h3><p>Recherche serveur téléphone/e-mail, filtres backend et pagination réelle.</p></div><span className="admin-sidebar-result"><CheckCircle2 size={14} /> {rows.length} résultat(s)</span></header><div className="admin-sidebar-toolbar"><label><Search size={15} /><input value={query} onChange={event => setQuery(event.target.value)} onKeyDown={event => event.key === 'Enter' && load(1)} placeholder="Téléphone ou e-mail..." /></label><select value={role} onChange={event => setRole(event.target.value)} aria-label="Filtrer par rôle"><option value="">Tous les rôles</option>{Object.entries(userRoleLabels).map(([key, label]) => <option value={key} key={key}>{label}</option>)}</select><select value={status} onChange={event => setStatus(event.target.value)} aria-label="Filtrer par statut"><option value="">Tous les statuts</option>{Object.entries(userStatusLabels).map(([key, label]) => <option value={key} key={key}>{label}</option>)}</select><button className="admin-sidebar-reset" onClick={reset}><RefreshCw size={14} /> Réinitialiser</button><button className="admin-sidebar-reset" onClick={() => load(page)} disabled={loading}><RefreshCw size={14} className={loading ? 'admin-sidebar-spin' : ''} /> Actualiser</button></div>{loading ? <AdminUsersState label="Chargement des utilisateurs..." /> : error ? <AdminUsersState label={error} error onRetry={() => load(page)} /> : !rows.length ? <AdminUsersState label={query || role || status ? 'Aucun utilisateur correspondant.' : 'Aucun utilisateur retourné par le backend.'} empty /> : <div className="admin-sidebar-table admin-users-table"><header><span>Utilisateur</span><span>Rôle</span><span>Contact</span><span>Inscription</span><span>Statut</span><span>Action</span></header>{rows.map(user => <div className="admin-sidebar-table-row" key={user.id}><span className="admin-user-cell"><i>{userName(user).slice(0, 1).toUpperCase()}</i><b>{userName(user)}<small>{userText(user.profile?.city || user.profile?.region)}</small></b></span><span>{userRole(user)}</span><span><small>{userText(user.email, userText(user.phone))}</small></span><span>{userDate(user.createdAt)}</span><Status>{userStatus(user)}</Status><button className="admin-user-view" onClick={() => openDetail(user)}>Consulter <Eye size={13} /></button></div>)}</div>}{!loading && !error && total > 0 && <footer className="admin-users-pagination"><span>Page {page} sur {totalPages} · {total} utilisateur(s)</span><div><button disabled={page <= 1} onClick={() => load(page - 1)} aria-label="Page précédente">‹</button><button disabled={page >= totalPages} onClick={() => load(page + 1)} aria-label="Page suivante">›</button></div></footer>}</section>{selected && <AdminUserDetail user={selected} actionId={actionId} onClose={() => setSelected(null)} onAction={action} />}</SidebarFrame>;
}
